const { Parser } = require("node-sql-parser");

const parser = new Parser();

const TENANT_COLUMN = "tenant_id";
const MAX_OR_BRANCHES = 64;

/*
 * Tables shared between every tenant.
 *
 * All tables NOT listed here are considered tenant-scoped.
 *
 * Example:
 * const GLOBAL_TABLES = new Set([
 *   "countries",
 *   "currencies",
 *   "languages"
 * ]);
 */
const GLOBAL_TABLES = new Set([]);

/**
 * Main function
 *
 * @param {string|number} userTenantId authenticated tenant ID
 * @param {string} sqlQuery SQL generated by NL -> SQL model
 *
 * @returns {
 *   pass: boolean,
 *   verdict: "PASS" | "FAIL",
 *   code: string,
 *   reason: string
 * }
 */
function checkTenantSql(userTenantId, sqlQuery) {
    const expectedTenant = normalizeValue(userTenantId);

    if (!expectedTenant) {
        return fail(
            "INVALID_TENANT_ID",
            "Tenant ID is required."
        );
    }

    if (!sqlQuery || typeof sqlQuery !== "string") {
        return fail(
            "EMPTY_SQL",
            "SQL query is required."
        );
    }

    let ast;

    try {
        ast = parser.astify(sqlQuery, {
            database: "MySQL",
        });
    } catch (error) {
        return fail(
            "SQL_PARSE_ERROR",
            `SQL could not be safely parsed: ${error.message}`
        );
    }

    /*
     * Block stacked queries:
     *
     * SELECT ...;
     * DELETE ...;
     */
    if (Array.isArray(ast)) {
        if (ast.length !== 1) {
            return fail(
                "MULTIPLE_STATEMENTS",
                "Only one SQL statement is allowed."
            );
        }

        ast = ast[0];
    }

    const result = validateStatement(
        ast,
        expectedTenant,
        new Set()
    );

    if (!result.pass) {
        return {
            verdict: "FAIL",
            tenantId: userTenantId,
            statementType: ast?.type || "unknown",
            ...result,
        };
    }

    return {
        pass: true,
        verdict: "PASS",
        code: "TENANT_ISOLATION_CONFIRMED",
        reason:
            `Query is restricted to tenant ${userTenantId}.`,
        tenantId: userTenantId,
        statementType: ast?.type || "unknown",
    };
}

/* =========================================================
   STATEMENT VALIDATION
   ========================================================= */

function validateStatement(
    ast,
    expectedTenant,
    inheritedSafeAliases = new Set()
) {
    if (!ast || typeof ast !== "object") {
        return fail(
            "INVALID_AST",
            "Invalid SQL structure."
        );
    }

    const type = String(ast.type || "").toLowerCase();

    switch (type) {
        case "select":
            return validateSelect(
                ast,
                expectedTenant,
                inheritedSafeAliases
            );

        case "insert":
        case "replace":
            return validateInsert(
                ast,
                expectedTenant,
                inheritedSafeAliases
            );

        case "update":
            return validateUpdate(
                ast,
                expectedTenant,
                inheritedSafeAliases
            );

        case "delete":
            return validateDelete(
                ast,
                expectedTenant,
                inheritedSafeAliases
            );

        default:
            /*
             * Block things such as:
             *
             * DROP
             * ALTER
             * TRUNCATE
             * CREATE
             * GRANT
             * USE
             */
            return fail(
                "STATEMENT_NOT_ALLOWED",
                `SQL statement "${type || "unknown"}" is not allowed.`
            );
    }
}

/* =========================================================
   SELECT
   ========================================================= */

function validateSelect(
    ast,
    expectedTenant,
    inheritedSafeAliases
) {
    /*
     * CTE:
     *
     * WITH tenant_orders AS (
     *    SELECT ...
     * )
     */
    const cteNames = new Set(
        (ast.with || [])
            .map((cte) =>
                normalizeName(cte?.name?.value)
            )
            .filter(Boolean)
    );

    /*
     * Validate every CTE independently.
     */
    for (const cte of ast.with || []) {
        if (!cte?.stmt?.ast) {
            return fail(
                "INVALID_CTE",
                "Unable to safely analyze CTE."
            );
        }

        const result = validateStatement(
            cte.stmt.ast,
            expectedTenant,
            inheritedSafeAliases
        );

        if (!result.pass) {
            return prefixFail(
                result,
                `CTE ${cte?.name?.value || "unknown"}`
            );
        }
    }

    /*
     * UNION / UNION ALL
     *
     * node-sql-parser links SELECT branches
     * using _next.
     */
    let branch = ast;
    let branchNumber = 1;

    const visited = new Set();

    while (branch) {
        if (visited.has(branch)) {
            return fail(
                "INVALID_UNION",
                "Invalid UNION structure."
            );
        }

        visited.add(branch);

        const result = validateSelectBranch(
            branch,
            expectedTenant,
            inheritedSafeAliases,
            cteNames
        );

        if (!result.pass) {
            return prefixFail(
                result,
                `SELECT/UNION branch ${branchNumber}`
            );
        }

        branch = branch._next || null;
        branchNumber++;
    }

    return ok();
}

function validateSelectBranch(
    ast,
    expectedTenant,
    inheritedSafeAliases,
    cteNames
) {
    const from = normalizeFrom(ast.from);

    /*
     * Validate derived tables:
     *
     * SELECT *
     * FROM (
     *   SELECT * FROM orders
     *   WHERE tenant_id = 101
     * ) x
     */
    for (const item of from) {
        const nestedAst = item?.expr?.ast;

        if (nestedAst && isStatementNode(nestedAst)) {
            const result = validateStatement(
                nestedAst,
                expectedTenant,
                inheritedSafeAliases
            );

            if (!result.pass) {
                return prefixFail(
                    result,
                    "Derived table"
                );
            }
        }
    }

    /*
     * Validate FROM + JOIN + WHERE.
     */
    const scopeResult = validateFromScope({
        from,
        where: ast.where,
        expectedTenant,
        inheritedSafeAliases,
        cteNames,
    });

    if (!scopeResult.pass) {
        return scopeResult;
    }

    /*
     * Now that outer aliases are known safe,
     * correlated subqueries may use them.
     *
     * Example:
     *
     * o.tenant_id = c.tenant_id
     */
    const nestedAreas = [
        ast.columns,
        ast.where,
        ast.having,
        ast.groupby,
        ast.orderby,
        ast.window,
        ast.qualify,
    ];

    for (const area of nestedAreas) {
        const nestedQueries =
            collectNestedStatements(area);

        for (const nested of nestedQueries) {
            const result = validateStatement(
                nested,
                expectedTenant,
                scopeResult.safeAliases
            );

            if (!result.pass) {
                return prefixFail(
                    result,
                    "Nested subquery"
                );
            }
        }
    }

    return ok();
}

/* =========================================================
   UPDATE
   ========================================================= */

function validateUpdate(
    ast,
    expectedTenant,
    inheritedSafeAliases
) {
    /*
     * Never allow:
     *
     * UPDATE orders
     * SET tenant_id = 202
     */
    for (const item of ast.set || []) {
        if (
            normalizeName(item?.column) === TENANT_COLUMN
        ) {
            return fail(
                "TENANT_ID_MODIFICATION_FORBIDDEN",
                "UPDATE cannot modify tenant_id."
            );
        }
    }

    const from = normalizeFrom(ast.table);

    const scopeResult = validateFromScope({
        from,
        where: ast.where,
        expectedTenant,
        inheritedSafeAliases,
        cteNames: new Set(),
    });

    if (!scopeResult.pass) {
        return scopeResult;
    }

    /*
     * Check subqueries in SET and WHERE.
     */
    const nested =
        collectNestedStatements([
            ast.set,
            ast.where,
        ]);

    for (const query of nested) {
        const result = validateStatement(
            query,
            expectedTenant,
            scopeResult.safeAliases
        );

        if (!result.pass) {
            return prefixFail(
                result,
                "UPDATE subquery"
            );
        }
    }

    return ok();
}

/* =========================================================
   DELETE
   ========================================================= */

function validateDelete(
    ast,
    expectedTenant,
    inheritedSafeAliases
) {
    const from = normalizeFrom(ast.from);

    const scopeResult = validateFromScope({
        from,
        where: ast.where,
        expectedTenant,
        inheritedSafeAliases,
        cteNames: new Set(),
    });

    if (!scopeResult.pass) {
        return scopeResult;
    }

    const nested =
        collectNestedStatements(ast.where);

    for (const query of nested) {
        const result = validateStatement(
            query,
            expectedTenant,
            scopeResult.safeAliases
        );

        if (!result.pass) {
            return prefixFail(
                result,
                "DELETE subquery"
            );
        }
    }

    return ok();
}

/* =========================================================
   INSERT
   ========================================================= */

function validateInsert(
    ast,
    expectedTenant,
    inheritedSafeAliases
) {
    /*
     * Block:
     *
     * INSERT ...
     * ON DUPLICATE KEY UPDATE tenant_id = ...
     */
    for (
        const item of
        ast?.on_duplicate_update?.set || []
    ) {
        if (
            normalizeName(item?.column) ===
            TENANT_COLUMN
        ) {
            return fail(
                "TENANT_ID_MODIFICATION_FORBIDDEN",
                "tenant_id cannot be modified."
            );
        }
    }

    const columns =
        (ast.columns || []).map(normalizeName);

    const tenantIndex =
        columns.indexOf(TENANT_COLUMN);

    if (tenantIndex === -1) {
        return fail(
            "MISSING_TENANT_ID",
            "INSERT must explicitly contain tenant_id."
        );
    }

    /*
     * INSERT ... VALUES
     */
    if (ast.values?.type === "values") {
        const rows = ast.values.values || [];

        if (!rows.length) {
            return fail(
                "INVALID_INSERT",
                "INSERT contains no values."
            );
        }

        for (
            let rowIndex = 0;
            rowIndex < rows.length;
            rowIndex++
        ) {
            const row =
                rows[rowIndex]?.value || [];

            const tenantExpression =
                row[tenantIndex];

            const literal =
                getLiteralInfo(tenantExpression);

            /*
             * checkTenantSql(id, sql) only has
             * two arguments, therefore it cannot know
             * the actual value bound to ?.
             */
            if (literal.kind === "param") {
                return fail(
                    "UNVERIFIED_TENANT_PARAMETER",
                    `INSERT row ${rowIndex + 1
                    } uses an unverified tenant parameter.`
                );
            }

            if (literal.kind !== "literal") {
                return fail(
                    "UNSAFE_TENANT_EXPRESSION",
                    `INSERT row ${rowIndex + 1
                    } tenant_id is not a simple literal.`
                );
            }

            if (
                literal.value !== expectedTenant
            ) {
                return fail(
                    "WRONG_TENANT_ID",
                    `INSERT row ${rowIndex + 1
                    } uses tenant ${literal.value
                    }; expected ${expectedTenant}.`
                );
            }
        }

        return ok();
    }

    /*
     * INSERT INTO archive(...)
     * SELECT ...
     */
    if (
        ast.values &&
        isStatementNode(ast.values)
    ) {
        const sourceResult =
            validateStatement(
                ast.values,
                expectedTenant,
                inheritedSafeAliases
            );

        if (!sourceResult.pass) {
            return prefixFail(
                sourceResult,
                "INSERT SELECT source"
            );
        }

        let branch = ast.values;
        let branchNumber = 1;

        while (branch) {
            if (!Array.isArray(branch.columns)) {
                return fail(
                    "UNVERIFIABLE_INSERT_SELECT",
                    "INSERT SELECT requires explicit SELECT columns."
                );
            }

            const targetTenantColumn =
                branch.columns[tenantIndex];

            const expression =
                targetTenantColumn?.expr;

            const literal =
                getLiteralInfo(expression);

            /*
             * SELECT 101
             */
            if (literal.kind === "literal") {
                if (
                    literal.value !== expectedTenant
                ) {
                    return fail(
                        "WRONG_TENANT_ID",
                        `INSERT SELECT branch ${branchNumber} writes tenant ${literal.value}.`
                    );
                }
            }

            /*
             * SELECT tenant_id
             */
            else if (
                !isTenantColumnRef(expression)
            ) {
                return fail(
                    "UNVERIFIABLE_INSERT_SELECT",
                    `Unable to verify tenant_id output in INSERT SELECT branch ${branchNumber}.`
                );
            }

            branch = branch._next || null;
            branchNumber++;
        }

        return ok();
    }

    return fail(
        "INVALID_INSERT",
        "Unable to verify INSERT tenant isolation."
    );
}

/* =========================================================
   FROM / JOIN VALIDATION
   ========================================================= */

function validateFromScope({
    from,
    where,
    expectedTenant,
    inheritedSafeAliases,
    cteNames,
}) {
    const scope =
        buildScope(from, cteNames);

    /*
     * For the initial research version,
     * reject RIGHT JOIN.
     *
     * This avoids incorrectly treating ON conditions
     * as row filters for the preserved side.
     */
    if (scope.rightJoins.length) {
        return fail(
            "RIGHT_JOIN_REJECTED",
            "RIGHT JOIN is rejected. Rewrite it as LEFT JOIN or INNER JOIN."
        );
    }

    /*
     * Root tables + INNER JOIN tables.
     */
    const coreAliases =
        scope.tenantEntries
            .filter(
                (entry) =>
                    entry.joinType !== "LEFT JOIN"
            )
            .map((entry) => entry.alias);

    /*
     * INNER JOIN ON clauses can safely
     * participate in equality propagation.
     */
    const innerJoinConditions =
        scope.entries
            .filter(
                (entry) =>
                    entry.joinType ===
                    "INNER JOIN" &&
                    entry.on
            )
            .map((entry) => entry.on);

    /*
     * Example:
     *
     * WHERE c.tenant_id = 101
     *
     * JOIN orders o
     * ON o.tenant_id = c.tenant_id
     */
    const predicate = andAll([
        where,
        ...innerJoinConditions,
    ]);

    const coreResult =
        analyzePredicate({
            predicate,
            requiredAliases: coreAliases,
            scope,
            inheritedSafeAliases,
            expectedTenant,
        });

    if (!coreResult.pass) {
        return coreResult;
    }

    const safeAliases =
        new Set(inheritedSafeAliases);

    for (const alias of coreAliases) {
        safeAliases.add(alias);
    }

    /*
     * LEFT JOIN must be checked separately.
     */
    const leftJoins =
        scope.tenantEntries.filter(
            (entry) =>
                entry.joinType === "LEFT JOIN"
        );

    for (const entry of leftJoins) {
        const leftPredicate =
            andAll([
                where,
                entry.on,
            ]);

        const result =
            analyzePredicate({
                predicate: leftPredicate,

                requiredAliases: [
                    entry.alias,
                ],

                scope,

                inheritedSafeAliases:
                    safeAliases,

                expectedTenant,
            });

        if (!result.pass) {
            return prefixFail(
                result,
                `LEFT JOIN table ${entry.table}`
            );
        }

        safeAliases.add(entry.alias);
    }

    return {
        pass: true,
        safeAliases,
    };
}

/* =========================================================
   BOOLEAN PREDICATE ANALYSIS
   ========================================================= */

function analyzePredicate({
    predicate,
    requiredAliases,
    scope,
    inheritedSafeAliases,
    expectedTenant,
}) {
    let branches;

    try {
        /*
         * Convert boolean expression to DNF.
         *
         * Example:
         *
         * (tenant=101 AND status='A')
         * OR
         * (tenant=101 AND status='B')
         *
         * becomes two security branches.
         */
        branches = toDNF(predicate);
    } catch (error) {
        return fail(
            "PREDICATE_TOO_COMPLEX",
            error.message
        );
    }

    /*
     * EVERY OR branch must be secure.
     */
    for (
        let i = 0;
        i < branches.length;
        i++
    ) {
        const result =
            analyzeConjunction({
                atoms: branches[i],
                requiredAliases,
                scope,
                inheritedSafeAliases,
                expectedTenant,
            });

        if (!result.pass) {
            return fail(
                result.code,
                branches.length > 1
                    ? `OR branch ${i + 1
                    }: ${result.reason}`
                    : result.reason
            );
        }
    }

    return ok();
}

/* =========================================================
   TENANT RELATIONSHIP ANALYSIS
   ========================================================= */

function analyzeConjunction({
    atoms,
    requiredAliases,
    scope,
    inheritedSafeAliases,
    expectedTenant,
}) {
    /*
     * Union-Find lets us understand:
     *
     * c.tenant_id = 101
     * o.tenant_id = c.tenant_id
     * oi.tenant_id = o.tenant_id
     *
     * => all resolve to 101
     */
    const unionFind =
        new UnionFind();

    const literalBindings =
        new Map();

    for (const alias of requiredAliases) {
        unionFind.add(alias);
    }

    /*
     * Outer correlated aliases are already
     * known to equal expectedTenant.
     */
    for (
        const alias of inheritedSafeAliases
    ) {
        unionFind.add(alias);

        bindLiteral(
            literalBindings,
            alias,
            expectedTenant
        );
    }

    for (const atom of atoms) {
        const result =
            consumeTenantAtom({
                atom,
                scope,
                unionFind,
                literalBindings,
            });

        if (!result.pass) {
            return result;
        }
    }

    /*
     * Resolve all equality groups.
     */
    const componentValues =
        new Map();

    for (
        const [alias, values]
        of literalBindings.entries()
    ) {
        const root =
            unionFind.find(alias);

        if (!componentValues.has(root)) {
            componentValues.set(
                root,
                new Set()
            );
        }

        for (const value of values) {
            componentValues
                .get(root)
                .add(value);
        }
    }

    /*
     * Detect:
     *
     * c.tenant_id = 101
     * o.tenant_id = c.tenant_id
     * o.tenant_id = 202
     */
    for (
        const values of
        componentValues.values()
    ) {
        if (values.size > 1) {
            return fail(
                "MULTIPLE_TENANTS",
                `Multiple tenant IDs detected: ${[...values].join(", ")
                }.`
            );
        }

        const value =
            [...values][0];

        if (
            value !== expectedTenant
        ) {
            return fail(
                "WRONG_TENANT_ID",
                `Query accesses tenant ${value}; expected ${expectedTenant}.`
            );
        }
    }

    /*
     * Every tenant table must eventually
     * resolve to expectedTenant.
     */
    for (
        const alias of requiredAliases
    ) {
        const root =
            unionFind.find(alias);

        const values =
            componentValues.get(root);

        if (
            !values ||
            values.size !== 1 ||
            !values.has(expectedTenant)
        ) {
            return fail(
                "MISSING_TENANT_ID",
                `Table/alias "${alias}" is not restricted to tenant ${expectedTenant}.`
            );
        }
    }

    return ok();
}

/* =========================================================
   SINGLE CONDITION
   ========================================================= */

function consumeTenantAtom({
    atom,
    scope,
    unionFind,
    literalBindings,
}) {
    if (
        !atom ||
        typeof atom !== "object"
    ) {
        return ok();
    }

    if (
        atom.type !== "binary_expr"
    ) {
        if (containsTenantRef(atom)) {
            return fail(
                "UNSAFE_TENANT_EXPRESSION",
                "tenant_id is used inside an unsupported expression."
            );
        }

        return ok();
    }

    const operator =
        String(atom.operator || "")
            .trim()
            .toUpperCase();

    const leftTenant =
        getTenantRef(
            atom.left,
            scope
        );

    const rightTenant =
        getTenantRef(
            atom.right,
            scope
        );

    if (
        leftTenant?.ambiguous ||
        rightTenant?.ambiguous
    ) {
        return fail(
            "AMBIGUOUS_TENANT_ID",
            "tenant_id is ambiguous because multiple tables are visible."
        );
    }

    /*
     * Safe:
     *
     * tenant_id = 101
     * 101 = tenant_id
     * o.tenant_id = c.tenant_id
     */
    if (operator === "=") {
        if (
            leftTenant &&
            rightTenant
        ) {
            unionFind.union(
                leftTenant.alias,
                rightTenant.alias
            );

            return ok();
        }

        if (
            leftTenant ||
            rightTenant
        ) {
            const tenant =
                leftTenant ||
                rightTenant;

            const other =
                leftTenant
                    ? atom.right
                    : atom.left;

            const literal =
                getLiteralInfo(other);

            if (literal.kind === "param") {
                return fail(
                    "UNVERIFIED_TENANT_PARAMETER",
                    "tenant_id uses an SQL parameter whose value cannot be verified."
                );
            }

            if (
                literal.kind !== "literal"
            ) {
                return fail(
                    "UNSAFE_TENANT_EXPRESSION",
                    "tenant_id must equal a tenant literal or another tenant_id."
                );
            }

            unionFind.add(
                tenant.alias
            );

            bindLiteral(
                literalBindings,
                tenant.alias,
                literal.value
            );

            return ok();
        }

        /*
         * Example:
         *
         * CAST(tenant_id AS UNSIGNED) = 101
         */
        if (
            containsTenantRef(atom)
        ) {
            return fail(
                "UNSAFE_TENANT_EXPRESSION",
                "Complex tenant_id equality is not allowed."
            );
        }

        return ok();
    }

    /*
     * tenant_id IN (101)
     *
     * allowed.
     */
    if (
        operator === "IN" &&
        leftTenant
    ) {
        const list =
            getExpressionList(
                atom.right
            );

        if (!list) {
            return fail(
                "UNSAFE_TENANT_EXPRESSION",
                "tenant_id IN must contain a literal."
            );
        }

        /*
         * tenant_id IN (101, 202)
         */
        if (list.length !== 1) {
            return fail(
                "MULTIPLE_TENANTS",
                "tenant_id IN (...) may contain only one tenant."
            );
        }

        const literal =
            getLiteralInfo(list[0]);

        if (literal.kind === "param") {
            return fail(
                "UNVERIFIED_TENANT_PARAMETER",
                "Unable to verify tenant_id IN (?) parameter."
            );
        }

        if (
            literal.kind !== "literal"
        ) {
            return fail(
                "UNSAFE_TENANT_EXPRESSION",
                "tenant_id IN must contain one literal tenant."
            );
        }

        unionFind.add(
            leftTenant.alias
        );

        bindLiteral(
            literalBindings,
            leftTenant.alias,
            literal.value
        );

        return ok();
    }

    /*
     * Reject:
     *
     * tenant_id != 101
     * tenant_id <> 101
     * tenant_id > 101
     * tenant_id < 101
     * tenant_id BETWEEN ...
     * tenant_id LIKE ...
     * tenant_id IS NOT NULL
     * tenant_id NOT IN (...)
     */
    if (
        leftTenant ||
        rightTenant ||
        containsTenantRef(atom)
    ) {
        return fail(
            "UNSAFE_TENANT_OPERATOR",
            `Operator "${atom.operator}" is not allowed with tenant_id.`
        );
    }

    return ok();
}

/* =========================================================
   OR / AND PROCESSING
   ========================================================= */

function toDNF(expression) {
    /*
     * No WHERE:
     *
     * one branch containing no tenant rule.
     */
    if (!expression) {
        return [[]];
    }

    if (
        expression.type ===
        "binary_expr"
    ) {
        const operator =
            String(
                expression.operator || ""
            )
                .trim()
                .toUpperCase();

        /*
         * A OR B
         */
        if (operator === "OR") {
            const left =
                toDNF(expression.left);

            const right =
                toDNF(expression.right);

            const result = [
                ...left,
                ...right,
            ];

            checkBranchCount(
                result.length
            );

            return result;
        }

        /*
         * A AND B
         */
        if (operator === "AND") {
            const left =
                toDNF(expression.left);

            const right =
                toDNF(expression.right);

            const result = [];

            for (const l of left) {
                for (const r of right) {
                    result.push([
                        ...l,
                        ...r,
                    ]);

                    checkBranchCount(
                        result.length
                    );
                }
            }

            return result;
        }
    }

    return [[expression]];
}

function checkBranchCount(count) {
    if (
        count > MAX_OR_BRANCHES
    ) {
        throw new Error(
            `Query contains more than ${MAX_OR_BRANCHES} boolean security branches.`
        );
    }
}

/* =========================================================
   SCOPE / TABLES
   ========================================================= */

function buildScope(
    from,
    cteNames
) {
    const entries = [];

    const nameToAlias =
        new Map();

    const rightJoins = [];

    for (const item of from) {
        /*
         * Ignore:
         *
         * derived tables
         * DUAL
         */
        if (
            !item ||
            !item.table
        ) {
            continue;
        }

        const table =
            normalizeName(
                item.table
            );

        const alias =
            normalizeName(
                item.as ||
                item.table
            );

        const joinType =
            normalizeJoin(
                item.join
            );

        const isCTE =
            cteNames.has(table);

        const isGlobal =
            GLOBAL_TABLES.has(table);

        const entry = {
            table,
            alias,
            joinType,
            on: item.on || null,

            /*
             * Physical non-global tables
             * require tenant isolation.
             */
            tenantScoped:
                !isCTE &&
                !isGlobal,
        };

        entries.push(entry);

        nameToAlias.set(
            alias,
            alias
        );

        if (!item.as) {
            nameToAlias.set(
                table,
                alias
            );
        }

        if (
            joinType ===
            "RIGHT JOIN"
        ) {
            rightJoins.push(entry);
        }
    }

    return {
        entries,

        nameToAlias,

        rightJoins,

        tenantEntries:
            entries.filter(
                (entry) =>
                    entry.tenantScoped
            ),
    };
}

/* =========================================================
   TENANT COLUMN DETECTION
   ========================================================= */

function getTenantRef(
    node,
    scope
) {
    const ref =
        unwrapColumnRef(node);

    if (!ref) {
        return null;
    }

    if (
        normalizeName(
            ref.column
        ) !== TENANT_COLUMN
    ) {
        return null;
    }

    const table =
        normalizeName(
            ref.table
        );

    /*
     * WHERE tenant_id = 101
     */
    if (!table) {
        const aliases =
            scope.tenantEntries.map(
                (entry) =>
                    entry.alias
            );

        /*
         * Only one table visible:
         * safe to resolve.
         */
        if (aliases.length === 1) {
            return {
                alias: aliases[0],
            };
        }

        /*
         * No local physical tenant table.
         * Could be CTE/derived output.
         */
        if (aliases.length === 0) {
            return {
                alias:
                    "__tenant_id__",
            };
        }

        /*
         * Multiple tables:
         *
         * WHERE tenant_id = 101
         *
         * is ambiguous.
         */
        return {
            ambiguous: true,
        };
    }

    return {
        alias:
            scope.nameToAlias.get(
                table
            ) || table,
    };
}

function unwrapColumnRef(node) {
    if (
        !node ||
        typeof node !== "object"
    ) {
        return null;
    }

    if (
        node.type === "column_ref"
    ) {
        return node;
    }

    if (
        node.type === "expr" &&
        node.expr?.type ===
        "column_ref"
    ) {
        return node.expr;
    }

    return null;
}

function isTenantColumnRef(node) {
    const ref =
        unwrapColumnRef(node);

    return Boolean(
        ref &&
        normalizeName(
            ref.column
        ) === TENANT_COLUMN
    );
}

/* =========================================================
   COMPLEX TENANT DETECTION
   ========================================================= */

function containsTenantRef(
    node,
    visited = new Set()
) {
    if (
        !node ||
        typeof node !== "object"
    ) {
        return false;
    }

    if (visited.has(node)) {
        return false;
    }

    visited.add(node);

    /*
     * Nested SELECT gets its own
     * tenant validation.
     */
    if (
        isStatementNode(node)
    ) {
        return false;
    }

    if (
        node.ast &&
        isStatementNode(node.ast)
    ) {
        return false;
    }

    if (
        isTenantColumnRef(node)
    ) {
        return true;
    }

    if (Array.isArray(node)) {
        return node.some(
            (value) =>
                containsTenantRef(
                    value,
                    visited
                )
        );
    }

    for (
        const [key, value]
        of Object.entries(node)
    ) {
        if (
            key === "loc" ||
            key === "_next" ||
            key === "with"
        ) {
            continue;
        }

        if (
            containsTenantRef(
                value,
                visited
            )
        ) {
            return true;
        }
    }

    return false;
}

/* =========================================================
   NESTED SUBQUERIES
   ========================================================= */

function collectNestedStatements(
    node
) {
    const result = [];

    const visited =
        new Set();

    const statements =
        new Set();

    function walk(value) {
        if (
            !value ||
            typeof value !== "object"
        ) {
            return;
        }

        if (visited.has(value)) {
            return;
        }

        visited.add(value);

        if (
            isStatementNode(value)
        ) {
            if (
                !statements.has(value)
            ) {
                statements.add(value);
                result.push(value);
            }

            return;
        }

        if (
            value.ast &&
            isStatementNode(
                value.ast
            )
        ) {
            if (
                !statements.has(
                    value.ast
                )
            ) {
                statements.add(
                    value.ast
                );

                result.push(
                    value.ast
                );
            }

            return;
        }

        if (Array.isArray(value)) {
            for (const item of value) {
                walk(item);
            }

            return;
        }

        for (
            const [key, child]
            of Object.entries(value)
        ) {
            if (
                key === "loc" ||
                key === "_next" ||
                key === "with"
            ) {
                continue;
            }

            walk(child);
        }
    }

    walk(node);

    return result;
}

/* =========================================================
   LITERALS
   ========================================================= */

function getLiteralInfo(node) {
    if (
        node === null ||
        node === undefined
    ) {
        return {
            kind: "unknown",
        };
    }

    if (
        typeof node !== "object"
    ) {
        return {
            kind: "literal",
            value:
                normalizeValue(node),
        };
    }

    if (
        node.type === "param"
    ) {
        return {
            kind: "param",
            value: node.value,
        };
    }

    const literalTypes =
        new Set([
            "number",
            "string",
            "single_quote_string",
            "double_quote_string",
            "natural_string",
            "backticks_quote_string",
            "bigint",
            "hex_string",
            "full_hex_string",
        ]);

    const type =
        String(
            node.type || ""
        ).toLowerCase();

    if (
        literalTypes.has(type)
    ) {
        return {
            kind: "literal",

            value:
                normalizeValue(
                    node.value
                ),
        };
    }

    return {
        kind: "unknown",
    };
}

function getExpressionList(node) {
    if (
        node?.type ===
        "expr_list" &&
        Array.isArray(node.value)
    ) {
        return node.value;
    }

    return null;
}

/* =========================================================
   UNION FIND
   ========================================================= */

class UnionFind {
    constructor() {
        this.parent =
            new Map();
    }

    add(value) {
        if (
            !this.parent.has(value)
        ) {
            this.parent.set(
                value,
                value
            );
        }
    }

    find(value) {
        this.add(value);

        const parent =
            this.parent.get(value);

        if (parent !== value) {
            this.parent.set(
                value,
                this.find(parent)
            );
        }

        return this.parent.get(
            value
        );
    }

    union(a, b) {
        const rootA =
            this.find(a);

        const rootB =
            this.find(b);

        if (rootA !== rootB) {
            this.parent.set(
                rootB,
                rootA
            );
        }
    }
}

/* =========================================================
   HELPERS
   ========================================================= */

function bindLiteral(
    map,
    alias,
    value
) {
    if (!map.has(alias)) {
        map.set(
            alias,
            new Set()
        );
    }

    map
        .get(alias)
        .add(
            normalizeValue(value)
        );
}

function andAll(expressions) {
    const items =
        expressions.filter(Boolean);

    if (!items.length) {
        return null;
    }

    return items
        .slice(1)
        .reduce(
            (left, right) => ({
                type: "binary_expr",
                operator: "AND",
                left,
                right,
            }),

            items[0]
        );
}

function normalizeFrom(from) {
    if (!from) {
        return [];
    }

    return Array.isArray(from)
        ? from
        : [from];
}

function normalizeJoin(join) {
    if (!join) {
        return null;
    }

    const value =
        String(join)
            .trim()
            .toUpperCase();

    if (value === "JOIN") {
        return "INNER JOIN";
    }

    return value;
}

function normalizeName(value) {
    if (
        value === null ||
        value === undefined
    ) {
        return "";
    }

    if (
        typeof value === "object"
    ) {
        if (
            value.value !== undefined
        ) {
            return normalizeName(
                value.value
            );
        }

        if (
            value.expr?.value !==
            undefined
        ) {
            return normalizeName(
                value.expr.value
            );
        }
    }

    return String(value)
        .replace(/^`|`$/g, "")
        .trim()
        .toLowerCase();
}

function normalizeValue(value) {
    if (
        value === null ||
        value === undefined
    ) {
        return null;
    }

    if (
        typeof value === "object" &&
        value.value !== undefined
    ) {
        return normalizeValue(
            value.value
        );
    }

    return String(value).trim();
}

function isStatementNode(node) {
    if (
        !node ||
        typeof node !== "object"
    ) {
        return false;
    }

    return [
        "select",
        "insert",
        "replace",
        "update",
        "delete",
    ].includes(
        String(
            node.type || ""
        ).toLowerCase()
    );
}

function ok(extra = {}) {
    return {
        pass: true,
        ...extra,
    };
}

function fail(code, reason) {
    return {
        pass: false,
        verdict: "FAIL",
        code,
        reason,
    };
}

function prefixFail(
    result,
    prefix
) {
    if (result.pass) {
        return result;
    }

    return fail(
        result.code,
        `${prefix}: ${result.reason}`
    );
}

module.exports = {
    checkTenantSql,
    GLOBAL_TABLES,
};